struct NumArray{n:usize,b:Vec<i32>,a:Vec<i32>}impl NumArray{fn new(a:Vec<i32>)->Self{let n=a.len();let mut x=Self{n,b:vec![0;n+1],a:a.clone()};for i in 0..n{x.add(i,a[i]);}x}fn add(&mut self,mut i:usize,d:i32){i+=1;while i<=self.n{self.b[i]+=d;i+=i&(!i+1);}}fn update(&mut self,i:i32,v:i32){let i=i as usize;let d=v-self.a[i];self.a[i]=v;self.add(i,d);}fn pref(&self,mut i:usize)->i32{let mut r=0;i+=1;while i>0{r+=self.b[i];i&=i-1;}r}fn sum_range(&self,l:i32,r:i32)->i32{self.pref(r as usize)-if l>0{self.pref(l as usize-1)}else{0}}}
